  caseText: `
    <p>MedServe is developing a digital service intended for a clearly defined group of customers. Before finalising its Business Model Canvas, the founders classify potential customers according to demographic, psychographic and behavioural patterns. They then identify the specific problems and desires of these customers and articulate the unique value their service will provide.</p>

    <p>The founders determine that the service can reach customers through both online and offline channels. They also evaluate the kind of customer relationship they want to establish, including the possibility of personalised service and automated interactions. Several external suppliers and strategic partners are identified because their participation may enhance the venture's capabilities or reduce risk.</p>

    <p>Rather than launching the complete service immediately, MedServe first conducts surveys and interviews to determine whether there is genuine interest. It subsequently develops a simplified version containing essential features and launches it to obtain real-world user data. A controlled small-scale release is then conducted with early adopters to identify potential challenges and obtain further insights. Finally, management develops financial models to estimate revenue streams, cost structures and profitability.</p>
  `,

